content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_deadball_booth_end",
 "name": "Deadball: the booth, how it ended",
 "set": "set_hughson_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "wide",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "none",
    "cut": "dissolve"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "That's the final from {venue}. {away} {awayScore}, {home} {homeScore}.",
     "And that's it. {winner} beat {loser}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "FINAL",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "They won it in their last at-bat. {decider.name} with {decider.play} in the {decider.inning}, and the dugout emptied.",
     "A walk-off. {decider.name}, {decider.play}, bottom of the {decider.inning}, and they're all over him."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "walkoff",
     "op": "=",
     "value": "true"
    },
    {
     "fact": "decider.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{decider.name} put them ahead in the {decider.inning} with {decider.play}, and they never gave it back.",
     "The lead for good came in the {decider.inning}, on {decider.play} by {decider.name}."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "decider",
     "side": "right",
     "at": 0.3,
     "for": 0
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "walkoff",
     "op": "=",
     "value": "false"
    },
    {
     "fact": "decider.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "That took {endedIn}. Both bullpens are empty.",
     "{endedIn} to settle it. Nobody wanted to go home."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "extras",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{winner} were {comebackSaid} at one point and came back to win it.",
     "Don't forget {winner} were {comebackSaid}. They kept chipping away."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "comebackSaid",
     "op": "has"
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "And {loser} never got a man home. That's a shutout."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "shutout",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b7",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{gameStar.name} was the best man on the field. {gameStar.hits} hits and {gameStar.rbi} driven in."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "gameStar.name",
     "op": "has"
    },
    {
     "fact": "gameStar.rbi",
     "op": ">",
     "value": 0
    },
    {
     "fact": "gameStar.hits",
     "op": ">",
     "value": 1
    }
   ]
  },
  {
   "id": "b8",
   "shot": {
    "cam": "cam2",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "For {col.name}, I'm {pbp.name}. Let's go back to the desk.",
     "That's all from up here. Over to the desk."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  }
 ]
}
